@js:
const baseUrlApi = `${source.key}api/comment?pageSize=20&site=${baseUrl.match(/api\/(.*?)$/)[1].replace('novel', 'web').replaceAll('/', '-')}`;

function formatComments(items, parentName) {
    if (!items.length) return '';
    return items.map(item => {
        let time = java.timeFormatUTC(item.createAt * 1000, 'yyyy-MM-dd HH:mm:ss', 0);
        let replyTag = parentName ? ` | @${parentName}` : '';
        let content = (parentName ? 'ㅤ' : '') + item.content;

        let block = `${parentName ? '└' + item.user.username : item.user.username} | ${time}${replyTag}\n${parentName ? content.replaceAll('\n', '\nㅤ') : content}`;

        if (item.replies.length) {
            block += '\n' + formatComments(item.replies, item.user.username, true);
        }
        return block;
    }).join(parentName ? '\n' : '\nㅤ\n');
}

const allComments = [];
let page = 0;
let hasMore = true;

while (hasMore && page < 5) {
    let res = JSON.parse(java.get(`${baseUrlApi}&page=${page}`, {}).body() || '{}');
    if (res.items.length) {
        allComments.push(formatComments(res.items));
        hasMore = page < (res.pageNumber - 1);
        page++;
    } else {
        hasMore = false;
    }
}

const Comment = allComments.length ? `\n💬 [评论区 | 时间倒序]：\n${allComments.join('\nㅤ\n')}`.replaceAll('::: star ', '评分：⭐×').replaceAll('::: details 点击展开', '').replace('\n:::\n', '') : '';

result + Comment;

images.listSelector:
@js:
let content;
try {
    result = JSON.parse(result)
    const config = getConfig()
    const resultList = []
    for (let ip = 0; ip < result.paragraphs.length; ip++) {
        let p = result.paragraphs[ip]
        if (/^<图片>http.+$/.test(p)) {
            p = '<img src="' + p.replace(/^<图片>/i, "") + '">'
            resultList.push(p)
            continue
        }

        function generateTran(i) {
            const chars = {
                baiduParagraphs: "ᵇ",
                youdaoParagraphs: "ʸ",
                gptParagraphs: "ᵍ",
                sakuraParagraphs: "ˢ"
            }
            if (config.translation === "并列") {
                const processed = []
                for (let ii = 0; ii < config.translationArr.length; ii++) {
                    let t = config.translationArr[ii]
                    if (result[t]) {
                        if (/^<图片>http.+$/.test(result[t][i])) {
                            let tmp = '<img src="' + result[t][i].replace(/^<图片>/i, "") + '">'
                            if (!processed.includes(tmp))
                                processed.push(tmp)
                            continue
                        }
                        processed.push((result[t][i] != "" ? chars[t] : "") + result[t][i].trim())
                        continue
                    }
                    processed.push("")
                }
                return processed.join("\n")
            } else {
                for (let tt = 0; tt < config.translationArr.length; tt++) {
                    let t = config.translationArr[tt]
                    if (result[t]) {
                        if (/^<图片>http.+$/.test(result[t][i])) {
                            let tmp = '<img src="' + result[t][i].replace(/^<图片>/i, "") + '">'
                            return tmp
                        }
                        return (result[t][i] != "" ? chars[t] : "") + result[t][i].trim()
                    }
                }
            }
        }
        switch (String(config.language)) {
            case "日文":
                resultList.push(p)
                break
            case "中文":
                resultList.push(generateTran(ip))
                break
            case "中日":
                resultList.push([generateTran(ip), p.trim()].join("\n"))
                break
            case "日中":
                resultList.push([p, generateTran(ip)].join("\n"))
                break
        }
    }
    content = resultList.join("\n")
} catch (e) {
    content = result;
}
content;
